function formatFans(n) {
  if (n == null) return '-'
  if (Math.abs(n) >= 10000) return (n / 10000).toFixed(1) + '万'
  return n.toLocaleString()
}

const fansPlatforms = computed(() => {
  const meta = fansData.value.platform_meta || {}
  const cur = fansData.value.current || {}
  const delta = fansData.value.delta || {}
  const all = [
    ...Object.keys(meta).filter(p => meta[p].group === 'domestic'),
    ...Object.keys(meta).filter(p => meta[p].group === 'international'),
  ]
  return all.filter(p => cur[p] != null).map(p => ({
    platform: p,
    label: meta[p]?.label || p,
    current: cur[p] ?? 0,
    delta: delta[p],
    group: meta[p]?.group || 'domestic',
  }))
})

const fansDomestic = computed(() => fansPlatforms.value.filter(p => p.group === 'domestic'))
const fansInternational = computed(() => fansPlatforms.value.filter(p => p.group === 'international'))

async function fetchFansHistory() {
  fansLoading.value = true
  try {
    const res = await fetch(`${API_BASE_URL}/api/zhihu/fans-history?days=2`)
    const json = await res.json()
    if (json.code === 200) {
      fansData.value = json.data
    }
  } catch (e) { /* silent */ }
  finally { fansLoading.value = false }
}
// ── 粉丝概览 END ────────────────────────────────────────

async function fetchStatus() {
  loading.value = true
  errorMsg.value = ''
  try {
    const res = await fetch(`${API_BASE_URL}/api/zhihu/system-status`)
    const json = await res.json()
    if (json.code !== 200) {
      errorMsg.value = `获取系统状态失败: ${json.msg || '未知错误'}`
      return
    }
    services.value = json.data.services || []
    now.value = json.data.now || ''
    todayError.value = json.data.today_error || ''
    envideo.value = json.data.envideo || {}
  } catch (e) {
    errorMsg.value = `网络错误: ${e?.message || e}`
  } finally {
    loading.value = false
  }
}

// 只有 charles / zoe / zoe_mp / zoe_video 这 4 个 key 后端支持一键启动
const STARTABLE_KEYS = ['charles', 'zoe', 'zoe_mp', 'zoe_video']

function canStart(svc) {
  if (!STARTABLE_KEYS.includes(svc.key)) return false
  const h = svc.heartbeat?.health
  // healthy / starting 状态不显示按钮 (启动期间也藏, 避免在 import 慢的窗口误重启)
  if (h === 'healthy' || h === 'starting') return false
  return true
}

function startButtonText(svc) {
  // stale / worker_stale = 进程可能还在但已卡死, 叫"重启" 更准确
  const h = svc.heartbeat?.health
  if (h === 'stale' || h === 'worker_stale') return '重启'
  return '启动'
}

async function startService(svc) {
  if (startingKey.value) return
  if (!confirm(`确认${startButtonText(svc)} ${svc.name} 吗?\n\n会先 kill 同名进程, 然后用 detached 模式拉起新进程.`)) return
  startingKey.value = svc.key
  startMsg.value = ''
  try {
    const res = await fetch(`${API_BASE_URL}/api/zhihu/system-service/start`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ key: svc.key }),
    })
    const json = await res.json()
    if (json.code !== 200) {
      startMsg.value = `启动 ${svc.name} 失败: ${json.msg || '未知错误'}`
      return
    }
    startMsg.value = `${json.msg} (PID=${json.data?.pid || '-'})`
    // 心跳文件在 service 启动 1~2 个 tick 后才会刷, 这里隔 3s 拉一次状态
    setTimeout(fetchStatus, 3000)
  } catch (e) {
    startMsg.value = `启动 ${svc.name} 出错: ${e?.message || e}`
  } finally {
    startingKey.value = ''
  }
}

function healthText(hb) {
  if (!hb) return '未知'
  const h = hb.health
  if (h === 'healthy') return '健康'
  if (h === 'starting') return '启动中'
  if (h === 'stopped') return '已停止'
  if (h === 'dead') return '已停止 (异常)'
  if (h === 'stale') return '心跳掉线'
  if (h === 'worker_stale') {
    // 把卡死的 worker 名字也带出来, 文案信息密度更高
    const issues = (hb.worker_issues || []).map((w) => w.name)
    return issues.length ? `子线程卡死 (${issues.join(', ')})` : '子线程卡死'
  }
  return '未启动'
}

// service 内有几个 worker 是 stale 的 (= 子线程卡死). 决定汇总条要不要红/橙
function workerStaleCount(svc) {
  return (svc.heartbeat?.workers || []).filter((w) => w.is_stale).length
}

// 折叠/展开切换
function toggleWorkers(key) {
  workersOpen.value = { ...workersOpen.value, [key]: !workersOpen.value[key] }
}

// 判断当前 service 的 worker 列表要不要展开:
// 1. 用户手动展开过 → 展开
// 2. 有 worker stale → 强制展开 (问题需要被看到, 不让用户漏掉)
// 3. 否则折叠
function isWorkersOpen(svc) {
  if (workersOpen.value[svc.key]) return true
  if (workerStaleCount(svc) > 0) return true
  return false
}

function formatAge(seconds) {
  if (seconds == null) return '-'
  if (seconds < 60) return `${Math.round(seconds)}s`
  if (seconds < 3600) return `${Math.round(seconds / 60)}min`
  return `${(seconds / 3600).toFixed(1)}h`
}

// 取某个 service 的 today 字段 (service 还没加载时返回空对象, 模板安全)
function getToday(key) {
  const svc = services.value.find((s) => s.key === key)
  return (svc && svc.today) || {}
}

