// 段 3: 评论自动回复 (zoe_video service 的 auto_comment_reply daemon 产出)
// 4 个平台始终都显示 (即使 0), 方便横向对比覆盖度.
// 跳转目标 /ethan?platform=xxx, EthanPublishStats.vue 已支持读 route.query.platform
// paused/permanent 来自 commentCfg (评论暂停开关), 给卡片渲染"已暂停"态.
const commentMetrics = computed(() => {
  const v = getToday('zoe_video')
  const pausedMap = {}
  for (const p of (commentCfg.value.platforms || [])) pausedMap[p.key] = p
  return [
    { key: 'weixin', label: '微信视频号', value: v.weixin_replies ?? 0, to: '/ethan?platform=weixin' },
    { key: 'douyin', label: '抖音', value: v.douyin_replies ?? 0, to: '/ethan?platform=douyin' },
    { key: 'xiaohongshu', label: '小红书', value: v.xiaohongshu_replies ?? 0, to: '/ethan?platform=xiaohongshu' },
    { key: 'geektime', label: '极客时间', value: v.geektime_replies ?? 0, to: '/ethan?platform=geektime' },
  ].map(c => ({
    ...c,
    paused: !!pausedMap[c.key]?.paused,
    permanent: !!pausedMap[c.key]?.permanent,
  }))
})

async function fetchCommentConfig() {
  try {
    const res = await fetch(`${API_BASE_URL}/api/zhihu/comment-reply/config`)
    const json = await res.json()
    if (json.code === 200) commentCfg.value = json.data
  } catch (e) {
    /* 拉不到就保持默认 (全运行中), 不打断看板 */
  }
}

// toggle 一个平台的评论自动回复. paused=true 暂停, false 恢复.
// 写文件后需重启 zoe_video 才真正生效 (后端 msg 会带这句提示).
async function toggleCommentPlatform(p) {
  if (commentToggling.value || p.permanent) return
  commentToggling.value = p.key
  commentMsg.value = ''
  try {
    const res = await fetch(`${API_BASE_URL}/api/zhihu/comment-reply/config`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ platform: p.key, paused: !p.paused }),
    })
    const json = await res.json()
    if (json.code === 200) {
      commentMsg.value = json.msg
      await fetchCommentConfig()
    } else {
      commentMsg.value = `切换失败: ${json.msg || '未知错误'}`
    }
  } catch (e) {
    commentMsg.value = `切换出错: ${e?.message || e}`
  } finally {
    commentToggling.value = ''
  }
}

onMounted(() => {
  fetchStatus()
  pollTimer = setInterval(fetchStatus, POLL_S * 1000)
  fetchFansHistory()
  fetchCommentConfig()
})
onUnmounted(() => {
  if (pollTimer) clearInterval(pollTimer)
})

